package capsule

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

// Failure modes (d@e 2026-11-09, trajectory cfaa8ee1, assignment
// 246a833fd6bf0948283c6d37). A report-only assignment ran a Python script
// from inside /workspace/platform; Python wrote __pycache__/*.pyc into the
// overlay. The subject tree digest (digestCanonicalSubjectTree) then differed
// from the binding's, so the freeze counted a changed subject, persisted a
// source candidate, and review rejected the stray bytecode.
//
//  1. Generated bytecode and test caches change the subject digest, so a
//     deliverables-only assignment looks like a source change.
//  2. The persisted candidate copy carries them (and must still digest the
//     same as the walk, or the reconstruction check fails).
//  3. Capsule.Diff reports them as source changes, so the source patch and
//     the bundle's ordered file effects name them.
//  4. Guard against over-exclusion: a real source change beside a pyc, and
//     look-alike names (a file named pyc, a directory named cache_pyc), must
//     still count.
func TestGeneratedSourcePath(t *testing.T) {
	for rel, want := range map[string]bool{
		"__pycache__":                         true,
		"tools/__pycache__/x.cpython-312.pyc": true,
		"a/b.pyc":                             true,
		"a/b.pyo":                             true,
		".pytest_cache/v/cache":               true,
		"a/.pytest_cache":                     true,
		"foo.pyc/bar.py":                      true,
		"x/__pycache__/sub/y.txt":             true,
		"a/b.py":                              false,
		"pyc":                                 false,
		"cache_pyc/file.go":                   false,
		"internal/capsule/x.go":               false,
	} {
		if got := generatedSourcePath(rel); got != want {
			t.Errorf("generatedSourcePath(%q) = %v, want %v", rel, got, want)
		}
	}
}

func TestSubjectDigestAndCopyIgnoreGeneratedBytecode(t *testing.T) {
	root := filepath.Join(t.TempDir(), "workspace", "platform")
	write := func(rel, body string) {
		p := filepath.Join(root, rel)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("tools/report.py", "print(1)")
	ctx := context.Background()
	clean, err := digestCanonicalSubjectTree(ctx, root)
	if err != nil {
		t.Fatal(err)
	}
	write("tools/__pycache__/report.cpython-312.pyc", "\x00bytecode")
	write("stray.pyc", "x")
	write(".pytest_cache/README", "x")
	dirty, err := digestCanonicalSubjectTree(ctx, root)
	if err != nil || dirty != clean {
		t.Fatalf("generated files changed the subject digest: %q vs %q (%v)", clean, dirty, err)
	}
	target := filepath.Join(t.TempDir(), "copy")
	if err := copyCanonicalSubjectTree(ctx, root, target); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(target, "tools", "__pycache__")); !os.IsNotExist(err) {
		t.Fatalf("copy carried __pycache__: %v", err)
	}
	copied, err := digestCanonicalSubjectTree(ctx, target)
	if err != nil || copied != clean {
		t.Fatalf("copy digest %q != %q (%v)", copied, clean, err)
	}
	write("tools/report.py", "print(2)")
	real, err := digestCanonicalSubjectTree(ctx, root)
	if err != nil || real == clean {
		t.Fatalf("a real source edit must change the digest: %v", err)
	}
}

func TestDropGeneratedSourceChanges(t *testing.T) {
	in := []FileChange{
		{Path: "/workspace/platform/tools/__pycache__", Kind: ChangeAdded, Mode: os.ModeDir},
		{Path: "workspace/platform/tools/__pycache__/r.cpython-312.pyc", Kind: ChangeAdded},
		{Path: "workspace/platform/tools/report.py", Kind: ChangeModified},
		{Path: "var/lib/artifact/deliverables/report.pdf", Kind: ChangeAdded},
		{Path: "workspace/platform/old.pyc", Kind: ChangeDeleted},
	}
	got := dropGeneratedSourceChanges(in)
	var paths []string
	for _, c := range got {
		paths = append(paths, c.Path)
	}
	want := []string{"workspace/platform/tools/report.py", "var/lib/artifact/deliverables/report.pdf", "workspace/platform/old.pyc"}
	if len(paths) != len(want) {
		t.Fatalf("got %v want %v", paths, want)
	}
	for i := range want {
		if paths[i] != want[i] {
			t.Fatalf("got %v want %v", paths, want)
		}
	}
	if only := dropGeneratedSourceChanges(in[:2]); len(only) != 0 {
		t.Fatalf("bytecode-only change set must be empty: %v", only)
	}
}
